    if (envKey) {
      this.backend = "env";
      this.cachedKey = normalizeKeyMaterial(envKey);
      return this.cachedKey;
    }
    if (!this.forceFileFallback) {
      try {
        const keyringMod = require2("@napi-rs/keyring");
        const entry = new keyringMod.Entry(SERVICE_NAME, ACCOUNT_NAME);
        let existing = entry.getPassword();
        if (!existing) {
          existing = randomBytes(32).toString("hex");
          entry.setPassword(existing);
        }
        this.backend = "os-keyring";
        this.cachedKey = normalizeKeyMaterial(existing);
        return this.cachedKey;
      } catch {
      }
    }
    fs.mkdirSync(this.dataDir, { recursive: true });
    const keyFile = path.join(this.dataDir, "master.key");
    let hexKey;
    if (fs.existsSync(keyFile)) {
      hexKey = fs.readFileSync(keyFile, "utf8").trim();
    } else {
      hexKey = randomBytes(32).toString("hex");
      fs.writeFileSync(keyFile, hexKey + "\n", { encoding: "utf8", mode: 384 });
